import sys
import math

def is_suitable(x):
    for a in range(1, int(math.isqrt(2 * x)) + 1):
        if (x - a * a) % a == 0:
            b = (x - a * a) // a
            if b > a:
                return True
    return False

def solve():
    N = int(sys.stdin.readline())
    count = 0
    x = 1
    while True:
        if is_suitable(x):
            count += 1
            if count == N:
                print(x)
                return
        x += 1

if __name__ == "__main__":
    solve()
